CREATE FUNCTION public.bar_member_tip_staff(_club_id uuid) RETURNS TABLE(id uuid,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT d.id,d.label FROM public.bar_counter_devices d WHERE auth.uid() IS NOT NULL AND d.club_id=_club_id AND d.active AND nullif(btrim(d.label),'') IS NOT NULL AND EXISTS(SELECT 1 FROM public.bar_counter_sessions s WHERE s.device_id=d.id AND s.club_id=d.club_id AND s.revoked_at IS NULL AND s.expires_at>now()) ORDER BY d.label,d.id; $$;
REVOKE ALL ON FUNCTION public.bar_member_tip_staff(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.bar_member_tip_staff(uuid) TO authenticated,service_role;
CREATE FUNCTION public._bar_member_tip_recipient(_club_id uuid,_staff_id uuid,_tab_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE recipient uuid;candidates uuid[]; BEGIN SELECT array_agg(id ORDER BY id) INTO candidates FROM public.bar_member_tip_staff(_club_id); IF _staff_id IS NOT NULL THEN IF NOT coalesce(_staff_id=ANY(candidates),false) THEN RAISE EXCEPTION 'Choose a person currently serving at this bar'; END IF; RETURN _staff_id; END IF; IF _tab_id IS NOT NULL THEN SELECT counter_device_id INTO recipient FROM public.bar_guest_tabs WHERE id=_tab_id AND club_id=_club_id; IF coalesce(recipient=ANY(candidates),false) THEN RETURN recipient; END IF; END IF; IF cardinality(candidates)=1 THEN RETURN candidates[1]; END IF; RAISE EXCEPTION 'Choose a person currently serving at this bar'; END; $$;
REVOKE ALL ON FUNCTION public._bar_member_tip_recipient(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.bar_member_tab_account_with_tip(_tab_id uuid,_token uuid,_club_member_id uuid,_tip numeric,_staff_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE t public.bar_guest_tabs%ROWTYPE;r jsonb;recipient uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to charge to your member account'; END IF; SELECT * INTO t FROM public.bar_guest_tabs WHERE id=_tab_id AND token=_token FOR UPDATE; IF NOT FOUND OR t.status<>'open' THEN RAISE EXCEPTION 'Only open tabs can be settled'; END IF; IF _tip>0 THEN recipient:=public._bar_member_tip_recipient(t.club_id,_staff_id,t.id); END IF; PERFORM public._bar_prepare_tip(t.club_id,t.id,NULL,_tip,recipient); r:=public.bar_qr_charge_guest_tab_member_session(t.id,t.token,_club_member_id); RETURN r||jsonb_build_object('tip',_tip,'total',(r->>'total')::numeric+_tip); END; $$;
REVOKE ALL ON FUNCTION public.bar_member_tab_account_with_tip(uuid,uuid,uuid,numeric,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.bar_member_tab_account_with_tip(uuid,uuid,uuid,numeric,uuid) TO authenticated,service_role;
CREATE FUNCTION public.bar_member_cart_account_with_tip(_club_id uuid,_club_member_id uuid,_lines jsonb,_tip numeric,_request_id uuid,_staff_id uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE r jsonb;t public.bar_guest_tabs%ROWTYPE;recipient uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to charge to your member account'; END IF; IF _request_id IS NULL THEN RAISE EXCEPTION 'Settlement reference required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_request_id::text,0)); SELECT * INTO t FROM public.bar_guest_tabs WHERE id=_request_id; IF FOUND THEN IF t.club_id IS DISTINCT FROM _club_id OR t.club_member_id IS DISTINCT FROM _club_member_id OR t.opened_source IS DISTINCT FROM 'member_tip_receipt' OR t.status IS DISTINCT FROM 'settled' THEN RAISE EXCEPTION 'Settlement reference does not match'; END IF; IF NOT EXISTS(SELECT 1 FROM public.club_members m WHERE m.id=_club_member_id AND m.club_id=_club_id AND m.status='active' AND (m.user_id=auth.uid() OR (m.email IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=auth.uid() AND lower(p.email)=lower(m.email))))) THEN RAISE EXCEPTION 'This membership does not belong to the signed-in account'; END IF; RETURN jsonb_build_object('ok',true,'already',true,'verification','session'); END IF; IF NOT EXISTS(SELECT 1 FROM public.clubs WHERE id=_club_id AND coalesce(bar_account_tab_enabled,true)) THEN RAISE EXCEPTION 'Member account charges are not enabled for this club'; END IF; IF _tip>0 THEN recipient:=public._bar_member_tip_recipient(_club_id,_staff_id); END IF; r:=public.bar_qr_charge_member_session(_club_id,_club_member_id,_lines); INSERT INTO public.bar_guest_tabs(id,club_id,guest_name,club_member_id,opened_source) VALUES(_request_id,_club_id,coalesce(r->>'member_name','Member'),_club_member_id,'member_tip_receipt'); PERFORM public._bar_prepare_tip(_club_id,_request_id,NULL,_tip,recipient); UPDATE public.bar_guest_tabs SET status='settled',closed_at=now(),settled_method='member_account' WHERE id=_request_id; RETURN r||jsonb_build_object('tip',_tip,'total',(r->>'total')::numeric+_tip); END; $$;
REVOKE ALL ON FUNCTION public.bar_member_cart_account_with_tip(uuid,uuid,jsonb,numeric,uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.bar_member_cart_account_with_tip(uuid,uuid,jsonb,numeric,uuid,uuid) TO authenticated,service_role;